          child: Column(
            children: [
              const Text(
                'PLATFORM',
                style: TextStyle(
                  color: blue,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 3,
                  fontSize: 12,
                ),
              ),
              const SizedBox(height: 14),
              const Text(
                'Complete Career\nDevelopment Platform',
