class DashboardCard extends StatefulWidget {
  final IconData icon;
  final String title;

  const DashboardCard({
    super.key,
    required this.icon,
    required this.title,
  });

  @override
  State<DashboardCard> createState() => _DashboardCardState();
}

class _DashboardCardState extends State<DashboardCard> {
  bool hover = false;

  @override
  Widget build(BuildContext context) {
    return MouseRegion(
      onEnter: (_) {
        setState(() => hover = true);
      },
      onExit: (_) {
        setState(() => hover = false);
      },
      child: InkWell(
        borderRadius: BorderRadius.circular(18),
        onTap: () {},
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 180),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(18),
            border: Border.all(
              color: hover ? blue : const Color(0xFFE5E7EB),
            ),
          ),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(
                widget.icon,
                size: 38,
                color: blue,
              ),
              const SizedBox(height: 15),
              Text(
                widget.title,
                textAlign: TextAlign.center,
                style: const TextStyle(
                  fontWeight: FontWeight.w800,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// Run `flutterfire configure` to replace this placeholder with project values.
class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError(
          'Run flutterfire configure to generate web Firebase options.');
    }
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
      case TargetPlatform.iOS:
      case TargetPlatform.macOS:
      case TargetPlatform.windows:
      case TargetPlatform.linux:
        throw UnsupportedError(
            'Run flutterfire configure to generate Firebase options.');
      default:
        throw UnsupportedError('Unsupported platform.');
    }
  }
}

const ink9 = Color(0xFF08111F);
const ink8 = Color(0xFF0B1626);
const ink7 = Color(0xFF2563EB);
const ink6 = Color(0xFF22D3EE);
const ink5 = Color(0xFF7C3AED);
const primary = Color(0xFF1717A8);
const ink4 = Color(0xFFF7F9FC);
const ink3 = Color(0xFF111827);
const ink2 = Color(0xFF64748B);
const ink = Color(0xFF171A2E);

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  final prefs = await SharedPreferences.getInstance();
  final firebase = FirebaseService(prefs);
  await firebase.initialize();
  final session = AppSession(prefs, firebase);
  await session.restore();
  runApp(
    ChangeNotifierProvider.value(
      value: session,
      child: const SasthraFirebaseApp(),
    ),
  );
}

class SasthraFirebaseApp extends StatelessWidget {
  const SasthraFirebaseApp({super.key});

  @override
  Widget build(BuildContext context) {
    final session = context.watch<AppSession>();
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: 'AI Career Guidance',
      themeMode: session.darkMode ? ThemeMode.dark : ThemeMode.light,
      theme: AppTheme.light(),
      darkTheme: AppTheme.dark(),
      home: session.loading
          ? const SplashScreen()
          : session.authenticated
              ? const CareerHome()
              : const FrontGate(),
    );
  }
}

class AppTheme {
  static ThemeData light() => ThemeData(
        useMaterial3: true,
        fontFamily: 'Arial',
        scaffoldBackgroundColor: lightBg,
        colorScheme: ColorScheme.fromSeed(seedColor: primary),
        inputDecorationTheme: const InputDecorationTheme(
          border: OutlineInputBorder(),
          filled: true,
          fillColor: Colors.white,
        ),
        cardTheme: const CardThemeData(elevation: 0),
      );

  static ThemeData dark() => ThemeData(
        useMaterial3: true,
        fontFamily: 'Arial',
        brightness: Brightness.dark,
        colorScheme: ColorScheme.fromSeed(
          seedColor: primary,
          brightness: Brightness.dark,
        ),
      );
}

