class UserProfile {
  final String uid;
  final String name;
  final String email;
  final String role;
  final String education;
  final String location;
  final String phone;
  final String bio;
  final int credits;
  final int rewards;
  final DateTime updatedAt;

  const UserProfile({
    required this.uid,
    required this.name,
    required this.email,
    this.role = 'Software Development',
    this.education = '',
    this.location = '',
    this.phone = '',
    this.bio = '',
    this.credits = 100,
    this.rewards = 0,
    required this.updatedAt,
  });

  UserProfile copyWith({
    String? name,
    String? email,
    String? role,
    String? education,
    String? location,
    String? phone,
    String? bio,
    int? credits,
    int? rewards,
  }) =>
      UserProfile(
        uid: uid,
        name: name ?? this.name,
        email: email ?? this.email,
        role: role ?? this.role,
        education: education ?? this.education,
        location: location ?? this.location,
        phone: phone ?? this.phone,
        bio: bio ?? this.bio,
        credits: credits ?? this.credits,
        rewards: rewards ?? this.rewards,
        updatedAt: DateTime.now(),
      );

  Map<String, dynamic> toMap() => {
        'uid': uid,
        'name': name,
        'email': email,
        'role': role,
        'education': education,
        'location': location,
        'phone': phone,
        'bio': bio,
        'credits': credits,
        'rewards': rewards,
        'updatedAt': Timestamp.fromDate(updatedAt),
      };

  factory UserProfile.fromMap(Map<String, dynamic> map, String uid) {
    final raw = map['updatedAt'];
    final date = raw is Timestamp ? raw.toDate() : DateTime.now();
    return UserProfile(
      uid: uid,
      name: map['name'] as String? ?? 'Career User',
      email: map['email'] as String? ?? '',
      role: map['role'] as String? ?? 'Software Development',
      education: map['education'] as String? ?? '',
      location: map['location'] as String? ?? '',
      phone: map['phone'] as String? ?? '',
      bio: map['bio'] as String? ?? '',
      credits: (map['credits'] as num?)?.toInt() ?? 100,
      rewards: (map['rewards'] as num?)?.toInt() ?? 0,
      updatedAt: date,
    );
  }
}

class ChatRecord {
  final String id;
  final String text;
  final bool fromUser;
  final DateTime createdAt;
  const ChatRecord({
    required this.id,
    required this.text,
    required this.fromUser,
    required this.createdAt,
  });
  Map<String, dynamic> toMap() => {
        'text': text,
        'fromUser': fromUser,
        'createdAt': Timestamp.fromDate(createdAt),
      };
  factory ChatRecord.fromDoc(DocumentSnapshot<Map<String, dynamic>> doc) {
    final m = doc.data() ?? {};
    final raw = m['createdAt'];
    return ChatRecord(
      id: doc.id,
      text: m['text'] as String? ?? '',
      fromUser: m['fromUser'] as bool? ?? false,
      createdAt: raw is Timestamp ? raw.toDate() : DateTime.now(),
    );
  }
}

class CrudRecord {
  final String id;
  final String title;
  final String description;
  final String category;
  final bool completed;
  final DateTime createdAt;
  const CrudRecord({
    required this.id,
    required this.title,
    required this.description,
    required this.category,
    required this.completed,
    required this.createdAt,
  });
  CrudRecord copyWith({
    String? title,
    String? description,
    String? category,
    bool? completed,
  }) =>
      CrudRecord(
        id: id,
        title: title ?? this.title,
        description: description ?? this.description,
        category: category ?? this.category,
        completed: completed ?? this.completed,
        createdAt: createdAt,
      );
  Map<String, dynamic> toMap() => {
        'title': title,
        'description': description,
        'category': category,
        'completed': completed,
        'createdAt': Timestamp.fromDate(createdAt),
      };
  factory CrudRecord.fromDoc(DocumentSnapshot<Map<String, dynamic>> doc) {
    final m = doc.data() ?? {};
    final raw = m['createdAt'];
    return CrudRecord(
      id: doc.id,
      title: m['title'] as String? ?? '',
      description: m['description'] as String? ?? '',
      category: m['category'] as String? ?? 'General',
      completed: m['completed'] as bool? ?? false,
      createdAt: raw is Timestamp ? raw.toDate() : DateTime.now(),
    );
  }
}

class FirebaseService {
  final SharedPreferences prefs;
  bool firebaseReady = false;
  FirebaseFirestore? firestore;
  FirebaseAuth? auth;

  FirebaseService(this.prefs);

  Future<void> initialize() async {
    try {
      if (Firebase.apps.isEmpty) {
        await Firebase.initializeApp(
            options: DefaultFirebaseOptions.currentPlatform);
      }
      firestore = FirebaseFirestore.instance;
      auth = FirebaseAuth.instance;
      firebaseReady = true;
    } catch (_) {
      firebaseReady = false;
    }
  }

  Future<UserCredential?> signUp(String email, String password) async {
    if (!firebaseReady || auth == null) return null;
    return auth!.createUserWithEmailAndPassword(
      email: email.trim(),
      password: password,
    );
  }

  Future<UserCredential?> signIn(String email, String password) async {
    if (!firebaseReady || auth == null) return null;
    return auth!.signInWithEmailAndPassword(
      email: email.trim(),
      password: password,
    );
  }

  Future<void> signOut() async {
    if (firebaseReady) await auth?.signOut();
  }

  DocumentReference<Map<String, dynamic>> userDoc(String uid) =>
      firestore!.collection('users').doc(uid);

  CollectionReference<Map<String, dynamic>> userCollection(
    String uid,
    String collection,
  ) =>
      userDoc(uid).collection(collection);

  Future<void> saveProfile(UserProfile profile) async {
    if (!firebaseReady) return;
    await userDoc(profile.uid).set(profile.toMap(), SetOptions(merge: true));
  }

  Future<UserProfile?> loadProfile(String uid) async {
    if (!firebaseReady) return null;
    final snap = await userDoc(uid).get();
    if (!snap.exists) return null;
    return UserProfile.fromMap(snap.data() ?? {}, uid);
  }

  Stream<List<ChatRecord>> chatStream(String uid) {
    if (!firebaseReady) return const Stream.empty();
    return userCollection(uid, 'chats')
        .orderBy('createdAt')
        .snapshots()
        .map((snap) => snap.docs.map(ChatRecord.fromDoc).toList());
  }

  Future<void> addChat(String uid, ChatRecord chat) async {
    if (!firebaseReady) return;
    await userCollection(uid, 'chats').doc(chat.id).set(chat.toMap());
  }

  Future<void> deleteChat(String uid, String id) async {
    if (!firebaseReady) return;
    await userCollection(uid, 'chats').doc(id).delete();
  }

  Stream<List<CrudRecord>> crudStream(String uid, String collection) {
    if (!firebaseReady) return const Stream.empty();
    return userCollection(uid, collection)
        .orderBy('createdAt', descending: true)
        .snapshots()
        .map((snap) => snap.docs.map(CrudRecord.fromDoc).toList());
  }

  Future<String?> createCrud(
      String uid, String collection, CrudRecord record) async {
    if (!firebaseReady) return null;
    final ref = await userCollection(uid, collection).add(record.toMap());
    return ref.id;
  }

  Future<void> updateCrud(
      String uid, String collection, CrudRecord record) async {
    if (!firebaseReady) return;
    await userCollection(uid, collection).doc(record.id).update(record.toMap());
  }

  Future<void> deleteCrud(String uid, String collection, String id) async {
    if (!firebaseReady) return;
    await userCollection(uid, collection).doc(id).delete();
  }
}

class AppSession extends ChangeNotifier {
  final SharedPreferences prefs;
  final FirebaseService firebase;
  bool loading = true;
  bool authenticated = false;
  bool darkMode = false;
  UserProfile? profile;
  String? demoUid;

  AppSession(this.prefs, this.firebase);

  String get uid => profile?.uid ?? demoUid ?? 'local-demo-user';
  String get displayName =>
      profile?.name.isNotEmpty == true ? profile!.name : 'Career User';

  Future<void> restore() async {
    darkMode = prefs.getBool('darkMode') ?? false;
    if (firebase.firebaseReady && firebase.auth?.currentUser != null) {
      final user = firebase.auth!.currentUser!;
      profile = await firebase.loadProfile(user.uid) ??
          UserProfile(
              uid: user.uid,
              name: user.displayName ?? 'Career User',
              email: user.email ?? '',
              updatedAt: DateTime.now());
      authenticated = true;
    } else if (prefs.getBool('demoAuthenticated') ?? false) {
      demoUid = prefs.getString('demoUid') ?? 'local-demo-user';
      profile = UserProfile(
        uid: demoUid!,
        name: prefs.getString('demoName') ?? 'Career User',
        email: prefs.getString('demoEmail') ?? 'demo@example.com',
        updatedAt: DateTime.now(),
      );
      authenticated = true;
    }
    loading = false;
    notifyListeners();
  }

  Future<String?> login(
      {required String email, required String password}) async {
    try {
      if (firebase.firebaseReady) {
        final credential = await firebase.signIn(email, password);
        final user = credential?.user;
        if (user == null) return 'Login failed.';
        profile = await firebase.loadProfile(user.uid) ??
            UserProfile(
                uid: user.uid,
                name: user.displayName ?? email.split('@').first,
                email: user.email ?? email,
                updatedAt: DateTime.now());
        await firebase.saveProfile(profile!);
        authenticated = true;
      } else {
        demoUid = 'demo-${email.hashCode.abs()}';
        profile = UserProfile(
            uid: demoUid!,
            name: email.split('@').first,
            email: email,
            updatedAt: DateTime.now());
        await prefs.setBool('demoAuthenticated', true);
        await prefs.setString('demoUid', demoUid!);
        await prefs.setString('demoEmail', email);
        await prefs.setString('demoName', profile!.name);
        authenticated = true;
      }
      notifyListeners();
      return null;
    } on FirebaseAuthException catch (e) {
      return e.message ?? e.code;
    } catch (e) {
      return e.toString();
    }
  }

  Future<String?> signUp(
      {required String name,
      required String email,
      required String password}) async {
    try {
      if (firebase.firebaseReady) {
        final credential = await firebase.signUp(email, password);
        final user = credential?.user;
        if (user == null) return 'Registration failed.';
        await user.updateDisplayName(name);
        profile = UserProfile(
            uid: user.uid, name: name, email: email, updatedAt: DateTime.now());
        await firebase.saveProfile(profile!);
      } else {
        demoUid = 'demo-${email.hashCode.abs()}';
        profile = UserProfile(
            uid: demoUid!, name: name, email: email, updatedAt: DateTime.now());
        await prefs.setBool('demoAuthenticated', true);
        await prefs.setString('demoUid', demoUid!);
        await prefs.setString('demoEmail', email);
        await prefs.setString('demoName', name);
      }
      authenticated = true;
      notifyListeners();
      return null;
    } on FirebaseAuthException catch (e) {
      return e.message ?? e.code;
    } catch (e) {
      return e.toString();
    }
  }

  Future<void> updateProfile(UserProfile next) async {
    profile = next;
    if (firebase.firebaseReady) await firebase.saveProfile(next);
    await prefs.setString('demoName', next.name);
    notifyListeners();
  }

  Future<void> toggleDark() async {
    darkMode = !darkMode;
    await prefs.setBool('darkMode', darkMode);
    notifyListeners();
  }

  Future<void> logout() async {
    await firebase.signOut();
    authenticated = false;
    profile = null;
    demoUid = null;
    await prefs.remove('demoAuthenticated');
    notifyListeners();
  }
}

class AuthScreen extends StatefulWidget {
  const AuthScreen({super.key});
  @override
  State<AuthScreen> createState() => _AuthScreenState();
}

class _AuthScreenState extends State<AuthScreen> {
  final formKey = GlobalKey<FormState>();
  final name = TextEditingController();
  final email = TextEditingController();
  final password = TextEditingController();
  bool register = false;
  bool busy = false;
  bool obscure = true;

  @override
  void dispose() {
    name.dispose();
    email.dispose();
    password.dispose();
    super.dispose();
  }

  Future<void> submit() async {
    if (!(formKey.currentState?.validate() ?? false)) return;
    setState(() => busy = true);
    final session = context.read<AppSession>();
    final error = register
        ? await session.signUp(
            name: name.text.trim(),
            email: email.text.trim(),
            password: password.text)
        : await session.login(
            email: email.text.trim(), password: password.text);
    if (!mounted) return;
    setState(() => busy = false);
    if (error != null) {
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text(error)));
    } else {
      Navigator.of(context).pop();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Center(
        child: SingleChildScrollView(
          padding: const EdgeInsets.all(24),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 460),
            child: Card(
              child: Padding(
                padding: const EdgeInsets.all(32),
                child: Form(
                  key: formKey,
                  child: Column(
                    children: [
                      Container(
                          width: 70,
                          height: 70,
                          decoration: BoxDecoration(
                              gradient:
                                  const LinearGradient(colors: [blue, purple]),
                              borderRadius: BorderRadius.circular(20)),
                          child: const Icon(Icons.auto_awesome,
                              color: Colors.white, size: 34)),
                      const SizedBox(height: 18),
                      Text(
                          register
                              ? 'Create your career account'
                              : 'Welcome back',
                          style: Theme.of(context)
                              .textTheme
                              .headlineSmall
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      const SizedBox(height: 8),
                      Text(register
                          ? 'Save your profile, projects and AI conversations.'
                          : 'Sign in to continue your personalized career workspace.'),
                      const SizedBox(height: 24),
                      if (register) ...[
                        TextFormField(
                            controller: name,
                            decoration: const InputDecoration(
                                labelText: 'Full name',
                                prefixIcon: Icon(Icons.person_outline)),
                            validator: (v) => v == null || v.trim().length < 2
                                ? 'Enter your name'
                                : null),
                        const SizedBox(height: 14),
                      ],
                      TextFormField(
                          controller: email,
                          keyboardType: TextInputType.emailAddress,
                          decoration: const InputDecoration(
                              labelText: 'Email',
                              prefixIcon: Icon(Icons.email_outlined)),
                          validator: (v) => v == null || !v.contains('@')
                              ? 'Enter a valid email'
                              : null),
                      const SizedBox(height: 14),
                      TextFormField(
                          controller: password,
                          obscureText: obscure,
                          decoration: InputDecoration(
                              labelText: 'Password',
                              prefixIcon: const Icon(Icons.lock_outline),
                              suffixIcon: IconButton(
                                  onPressed: () =>
                                      setState(() => obscure = !obscure),
                                  icon: Icon(obscure
                                      ? Icons.visibility
                                      : Icons.visibility_off))),
                          validator: (v) => v == null || v.length < 6
                              ? 'Minimum 6 characters'
                              : null),
                      const SizedBox(height: 20),
                      SizedBox(
                          width: double.infinity,
                          child: FilledButton.icon(
                              onPressed: busy ? null : submit,
                              icon: busy
                                  ? const SizedBox(
                                      width: 18,
                                      height: 18,
                                      child: CircularProgressIndicator(
                                          strokeWidth: 2))
                                  : Icon(register
                                      ? Icons.person_add
                                      : Icons.login),
                              label:
                                  Text(register ? 'CREATE ACCOUNT' : 'LOGIN'))),
                      const SizedBox(height: 12),
                      TextButton(
                          onPressed: busy
                              ? null
                              : () => setState(() => register = !register),
                          child: Text(register
                              ? 'Already have an account? Login'
                              : 'New here? Create an account')),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

