class Profile {
  final String? name;
  final String? role;
  final String? education;
  final String? location;
  final String? phone;
  final String? bio;

  Profile({this.name, this.role, this.education, this.location, this.phone, this.bio});

  Profile copyWith({
    String? name,
    String? role,
    String? education,
    String? location,
    String? phone,
    String? bio,
  }) {
    return Profile(
      name: name ?? this.name,
      role: role ?? this.role,
      education: education ?? this.education,
      location: location ?? this.location,
      phone: phone ?? this.phone,
      bio: bio ?? this.bio,
    );
  }
}

class ProfileDialog extends StatefulWidget {
  const ProfileDialog({super.key});

  @override
  State<ProfileDialog> createState() => _ProfileDialogState();
}

class _ProfileDialogState extends State<ProfileDialog> {
  late final TextEditingController name;
  late final TextEditingController role;
  late final TextEditingController education;
  late final TextEditingController location;
  late final TextEditingController phone;
  late final TextEditingController bio;

  @override
  void initState() {
    super.initState();

    // Initialize controllers first to prevent late initialization errors
    name = TextEditingController();
    role = TextEditingController();
    education = TextEditingController();
    location = TextEditingController();
    phone = TextEditingController();
    bio = TextEditingController();

    // Safely fetch data after the first build frame
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final p = context.read<AppSession>().profile;
      if (p != null) {
        name.text = p.name ?? '';
        role.text = p.role ?? '';
        education.text = p.education ?? '';
        location.text = p.location ?? '';
        phone.text = p.phone ?? '';
        bio.text = p.bio ?? '';
      }
    });
  }

  @override
  void dispose() {
    name.dispose();
    role.dispose();
    education.dispose();
    location.dispose();
    phone.dispose();
    bio.dispose();
    super.dispose();
  }

  Future<void> save() async {
    final s = context.read<AppSession>();
    final p = s.profile;
    if (p == null) return;

    await s.updateProfile(p.copyWith(
      name: name.text.trim(),
      role: role.text.trim(),
      education: education.text.trim(),
      location: location.text.trim(),
      phone: phone.text.trim(),
      bio: bio.text.trim(),
    ));

    if (mounted) {
      Navigator.pop(context);
    }
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      title: const Text('Personalized profile'),
      content: SizedBox(
        width: 500,
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min, // Prevents unnecessary vertical stretching
            children: [
              TextField(
                controller: name,
                decoration: const InputDecoration(labelText: 'Name'),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: role,
                decoration: const InputDecoration(labelText: 'Target role'),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: education,
                decoration: const InputDecoration(labelText: 'Education'),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: location,
                decoration: const InputDecoration(labelText: 'Location'),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: phone,
                decoration: const InputDecoration(labelText: 'Phone'),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: bio,
                maxLines: 3,
                decoration: const InputDecoration(labelText: 'Bio'),
              ),
            ],
          ),
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context),
          child: const Text('Cancel'),
        ),
        FilledButton(
          onPressed: save,
          child: const Text('Save'),
        ),
      ],
    );
  }
}

