class AiChatPanel extends StatefulWidget {
  const AiChatPanel({super.key});
  @override
  State<AiChatPanel> createState() => _AiChatPanelState();
}

class _AiChatPanelState extends State<AiChatPanel> {
  final input = TextEditingController();
  final scroll = ScrollController();
  final List<ChatRecord> local = [];
  bool busy = false;
  String error = '';
  @override
  void dispose() {
    input.dispose();
    scroll.dispose();
    super.dispose();
  }

  Future<void> send(String text) async {
    final t = text.trim();
    if (t.isEmpty || busy) return;
    final session = context.read<AppSession>();
    final user = ChatRecord(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        text: t,
        fromUser: true,
        createdAt: DateTime.now());
    setState(() {
      local.add(user);
      busy = true;
      error = '';
    });
    input.clear();
    final reply = await AiService().generate(t, session.profile);
    final ai = ChatRecord(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        text: reply,
        fromUser: false,
        createdAt: DateTime.now());
    setState(() {
      local.add(ai);
      busy = false;
    });
    if (session.firebase.firebaseReady) {
      await session.firebase.addChat(session.uid, user);
      await session.firebase.addChat(session.uid, ai);
    }
    _scroll();
  }

  void _scroll() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && scroll.hasClients)
        scroll.animateTo(scroll.position.maxScrollExtent,
            duration: const Duration(milliseconds: 250), curve: Curves.easeOut);
    });
  }

  @override
  Widget build(BuildContext context) => Column(children: [
        Container(
            height: 62,
            padding: const EdgeInsets.symmetric(horizontal: 16),
            color: primary,
            child: const Row(children: [
              Icon(Icons.auto_awesome, color: Colors.white),
              SizedBox(width: 8),
              Text('AI Career Copilot',
                  style: TextStyle(
                      color: Colors.white,
                      fontWeight: FontWeight.w900,
                      fontSize: 17))
            ])),
        Expanded(
            child: local.isEmpty
                ? _empty()
                : ListView.builder(
                    controller: scroll,
                    padding: const EdgeInsets.all(14),
                    itemCount: local.length,
                    itemBuilder: (_, i) {
                      final m = local[i];
                      return Align(
                          alignment: m.fromUser
                              ? Alignment.centerRight
                              : Alignment.centerLeft,
                          child: Container(
                              constraints: const BoxConstraints(maxWidth: 340),
                              margin: const EdgeInsets.only(bottom: 8),
                              padding: const EdgeInsets.all(12),
                              decoration: BoxDecoration(
                                  color: m.fromUser
                                      ? primary
                                      : Colors.grey.shade100,
                                  borderRadius: BorderRadius.circular(13)),
                              child: Text(m.text,
                                  style: TextStyle(
                                      color:
                                          m.fromUser ? Colors.white : ink))));
                    })),
        if (busy) const LinearProgressIndicator(minHeight: 2),
        SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
            child: Row(
                children: [
              'Improve my resume',
              'Prepare for interview',
              'Build a career roadmap',
              'Coding practice'
            ]
                    .map((x) => Padding(
                        padding: const EdgeInsets.only(right: 6),
                        child: ActionChip(
                            label: Text(x), onPressed: () => send(x))))
                    .toList())),
        Padding(
            padding: const EdgeInsets.all(10),
            child: Row(children: [
              Expanded(
                  child: TextField(
                      controller: input,
                      onSubmitted: send,
                      decoration: const InputDecoration(
                          hintText: 'Ask your AI career copilot...'))),
              const SizedBox(width: 7),
              IconButton.filled(
                  onPressed: () => send(input.text),
                  icon: const Icon(Icons.send))
            ]))
      ]);
  Widget _empty() => const Center(
      child: Padding(
          padding: EdgeInsets.all(20),
          child: Text(
              'Ask about resumes, interviews, coding, skills, projects or career planning.',
              textAlign: TextAlign.center)));
}

class AiService {
  Future<String> generate(String prompt, UserProfile? profile) async {
    try {
      if (Firebase.apps.isEmpty) return _local(prompt, profile);
      final ai = FirebaseAI.googleAI();
      final model = ai.generativeModel(model: 'gemini-3.1-flash-lite');
      final context =
          'User name: ${profile?.name ?? 'Career User'}; target role: ${profile?.role ?? 'Software Development'}; education: ${profile?.education ?? ''}; location: ${profile?.location ?? ''}.';
      final response = await model.generateContent([
        Content.text(
            '$context\nYou are an AI career copilot. Give practical, concise career guidance. User request: $prompt')
      ]);
      return response.text?.trim().isNotEmpty == true
          ? response.text!.trim()
          : _local(prompt, profile);
    } catch (_) {
      return _local(prompt, profile);
    }
  }

  String _local(String prompt, UserProfile? profile) {
    final p = prompt.toLowerCase();
    if (p.contains('resume'))
      return 'For your resume, tailor the summary to ${profile?.role ?? 'your target role'}, quantify achievements, and keep skills aligned with the job description.';
    if (p.contains('interview'))
      return 'Practice a 60-second introduction, three STAR stories, role-specific technical questions, and two questions for the interviewer.';
    if (p.contains('coding'))
      return 'Start with arrays, strings, hash maps, recursion, sorting, and complexity analysis. Solve one timed problem daily.';
    if (p.contains('roadmap'))
      return 'Build a roadmap around your target role: fundamentals → projects → assessment → interview practice → applications.';
    return 'I can help with your resume, interview preparation, coding practice, projects, skills, portfolio and career roadmap.';
  }
}

