class ProfileFeaturePage extends StatefulWidget {
  final String title;
  final String subtitle;
  final String collection;
  final IconData icon;
  const ProfileFeaturePage(
      {super.key,
      required this.title,
      required this.subtitle,
      required this.collection,
      required this.icon});
  @override
  State<ProfileFeaturePage> createState() => _ProfileFeaturePageState();
}

class _ProfileFeaturePageState extends State<ProfileFeaturePage> {
  final title = TextEditingController();
  final desc = TextEditingController();
  bool saving = false;
  @override
  void dispose() {
    title.dispose();
    desc.dispose();
    super.dispose();
  }

  Future<void> add() async {
    if (title.text.trim().isEmpty) return;
    final s = context.read<AppSession>();
    final record = CrudRecord(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        title: title.text.trim(),
        description: desc.text.trim(),
        category: widget.title,
        completed: false,
        createdAt: DateTime.now());
    setState(() => saving = true);
    await s.firebase.createCrud(s.uid, widget.collection, record);
    title.clear();
    desc.clear();
    if (mounted) setState(() => saving = false);
  }

  Future<void> remove(String id) async {
    final s = context.read<AppSession>();
    await s.firebase.deleteCrud(s.uid, widget.collection, id);
  }

  @override
  Widget build(BuildContext context) => PageFrame(
      title: widget.title,
      subtitle: widget.subtitle,
      child: Column(children: [
        Panel(
            child: Column(children: [
          TextField(
              controller: title,
              decoration: InputDecoration(
                  labelText: '${widget.title} title',
                  prefixIcon: Icon(widget.icon))),
          const SizedBox(height: 10),
          TextField(
              controller: desc,
              maxLines: 3,
              decoration: const InputDecoration(labelText: 'Description')),
          const SizedBox(height: 10),
          Align(
              alignment: Alignment.centerRight,
              child: FilledButton.icon(
                  onPressed: saving ? null : add,
                  icon: const Icon(Icons.add),
                  label: const Text('Add')))
        ])),
        const SizedBox(height: 15),
        StreamBuilder<List<CrudRecord>>(
            stream: context
                .read<AppSession>()
                .firebase
                .crudStream(context.read<AppSession>().uid, widget.collection),
            builder: (context, snap) {
              final list = snap.data ?? [];
              if (list.isEmpty)
                return const Panel(
                    child:
                        Text('No records yet. Add your first record above.'));
              return Column(
                  children: list
                      .map((r) => Padding(
                          padding: const EdgeInsets.only(bottom: 8),
                          child: Panel(
                              child: ListTile(
                                  leading: Icon(widget.icon, color: primary),
                                  title: Text(r.title,
                                      style: const TextStyle(
                                          fontWeight: FontWeight.w800)),
                                  subtitle: Text(r.description),
                                  trailing: IconButton(
                                      onPressed: () => remove(r.id),
                                      icon: const Icon(Icons.delete_outline,
                                          color: Colors.red))))))
                      .toList());
            })
      ]));
}

