class InterviewNotesFeature1Page extends StatefulWidget {
  const InterviewNotesFeature1Page({super.key});

  @override
  State<InterviewNotesFeature1Page> createState() =>
      _InterviewNotesFeature1PageState();
}

class _InterviewNotesFeature1PageState
    extends State<InterviewNotesFeature1Page> {
  final TextEditingController titleController = TextEditingController();
  final TextEditingController descriptionController = TextEditingController();
  final List<String> localItems = <String>[];
  bool loading = false;
  bool compact = false;
  int selectedTab = 0;

  @override
  void dispose() {
    titleController.dispose();
    descriptionController.dispose();
    super.dispose();
  }

  Future<void> addLocal() async {
    final title = titleController.text.trim();
    if (title.isEmpty) return;
    setState(() {
      loading = true;
      localItems.add(title);
    });
    titleController.clear();
    descriptionController.clear();
    final session = context.read<AppSession>();
    if (session.firebase.firebaseReady) {
      final record = CrudRecord(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        title: title,
        description: descriptionController.text,
        category: 'interviewnotes',
        completed: false,
        createdAt: DateTime.now(),
      );
      await session.firebase.createCrud(session.uid, 'interviewnotes', record);
    }
    if (mounted) setState(() => loading = false);
  }

  void removeLocal(int index) {
    if (index < 0 || index >= localItems.length) return;
    setState(() => localItems.removeAt(index));
  }

  void toggleCompact() {
    setState(() => compact = !compact);
  }

  void selectTab(int value) {
    setState(() => selectedTab = value);
  }

  @override
  Widget build(BuildContext context) {
    return PageFrame(
      title: 'Interview Notes',
      subtitle:
          'Stateful interview notes workspace with persistence-ready controls',
      child: Column(
        children: [
          Panel(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    const Icon(Icons.auto_awesome, color: primary),
                    const SizedBox(width: 10),
                    const Expanded(
                        child: Text('Workspace controls',
                            style: TextStyle(fontWeight: FontWeight.w900))),
                    IconButton(
                        onPressed: toggleCompact,
                        icon: Icon(
                            compact ? Icons.view_agenda : Icons.view_list)),
                  ],
                ),
                const SizedBox(height: 12),
                TextField(
                    controller: titleController,
                    decoration: const InputDecoration(labelText: 'Title')),
                const SizedBox(height: 10),
                TextField(
                    controller: descriptionController,
                    maxLines: 3,
                    decoration:
                        const InputDecoration(labelText: 'Description')),
                const SizedBox(height: 10),
                Row(
                  children: [
                    FilledButton.icon(
                        onPressed: loading ? null : addLocal,
                        icon: const Icon(Icons.add),
                        label: const Text('Create')),
                    const SizedBox(width: 8),
                    OutlinedButton(
                        onPressed: () => setState(() => localItems.clear()),
                        child: const Text('Clear local items')),
                  ],
                ),
              ],
            ),
          ),
          const SizedBox(height: 12),
          NavigationBar(
            selectedIndex: selectedTab,
            onDestinationSelected: selectTab,
            destinations: const [
              NavigationDestination(
                  icon: Icon(Icons.list_alt), label: 'Records'),
              NavigationDestination(
                  icon: Icon(Icons.analytics_outlined), label: 'Analytics'),
              NavigationDestination(
                  icon: Icon(Icons.settings_outlined), label: 'Settings'),
            ],
          ),
          const SizedBox(height: 12),
          if (selectedTab == 0) _records(),
          if (selectedTab == 1) _analytics(),
          if (selectedTab == 2) _settings(),
        ],
      ),
    );
  }

  Widget _records() {
    if (localItems.isEmpty) {
      return const Panel(
          child: Text('No local records yet. Create your first item above.'));
    }
    return Column(
      children: localItems.asMap().entries.map((entry) {
        final index = entry.key;
        final value = entry.value;
        return Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: Panel(
            child: ListTile(
              leading: CircleAvatar(child: Text('{index}')),
              title: Text(value,
                  style: const TextStyle(fontWeight: FontWeight.w800)),
              subtitle: Text('Created locally • record {index}'),
              trailing: IconButton(
                  onPressed: () => removeLocal(index),
                  icon: const Icon(Icons.delete_outline, color: Colors.red)),
            ),
          ),
        );
      }).toList(),
    );
  }

  Widget _analytics() {
    final count = localItems.length;
    final readiness = count == 0 ? 0.0 : (count / 10).clamp(0.0, 1.0);
    return Panel(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
