class FeatureState001 extends ChangeNotifier {
  bool active = false;
  int count = 0;
  String status = 'idle';
  void start() {
    active = true;
    status = 'running';
    notifyListeners();
  }

  void stop() {
    active = false;
    status = 'stopped';
    notifyListeners();
  }

  void increment() {
    count++;
    notifyListeners();
  }

  void reset() {
    active = false;
    count = 0;
    status = 'idle';
    notifyListeners();
  }
}

