class DiagnosticsPage extends StatefulWidget {
  const DiagnosticsPage({super.key});
  @override
  State<DiagnosticsPage> createState() => _DiagnosticsPageState();
}

class _DiagnosticsPageState extends State<DiagnosticsPage> {
  final List<String> checks = <String>[];
  Future<void> runChecks() async {
    final session = context.read<AppSession>();
    setState(() {
      checks.clear();
      checks.add('SharedPreferences: OK');
    });
    setState(() {
      checks.add(session.firebase.firebaseReady
          ? 'Firebase: CONNECTED'
          : 'Firebase: LOCAL FALLBACK');
    });
    setState(() {
      checks.add(session.authenticated
          ? 'Authentication: SIGNED IN'
          : 'Authentication: SIGNED OUT');
    });
    setState(() {
      checks.add('Provider: ACTIVE');
    });
    setState(() {
      checks.add('AI service: READY WITH FALLBACK');
    });
  }

  @override
  Widget build(BuildContext context) => PageFrame(
      title: 'Diagnostics',
      subtitle: 'Check local app services',
      child: Panel(
          child: Column(children: [
        FilledButton.icon(
            onPressed: runChecks,
            icon: const Icon(Icons.health_and_safety),
            label: const Text('Run diagnostics')),
        const SizedBox(height: 12),
        ...checks.map((x) => ListTile(
            leading: const Icon(Icons.check_circle, color: Colors.green),
            title: Text(x)))
      ])));
}

// Generated architecture contains stateful feature modules and reusable state services.

// Reusable Firebase CRUD controllers, form state and analytics contracts.

class FirebaseCrudController001 extends ChangeNotifier {
  final FirebaseService service;
  final String uid;
  final String collection = 'module_001';
  bool busy = false;
  String lastError = '';
  List<CrudRecord> cache = <CrudRecord>[];

  FirebaseCrudController001(this.service, this.uid);

  Stream<List<CrudRecord>> watch() {
    return service.crudStream(uid, collection);
  }

  Future<void> create(String title, String description) async {
    busy = true;
    lastError = '';
    notifyListeners();
    try {
      final record = CrudRecord(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        title: title.trim(),
        description: description.trim(),
        category: collection,
        completed: false,
        createdAt: DateTime.now(),
      );
      await service.createCrud(uid, collection, record);
    } catch (e) {
      lastError = e.toString();
    } finally {
      busy = false;
      notifyListeners();
    }
  }

  Future<void> update(CrudRecord record) async {
    busy = true;
    lastError = '';
    notifyListeners();
    try {
      await service.updateCrud(uid, collection, record);
    } catch (e) {
      lastError = e.toString();
    } finally {
      busy = false;
      notifyListeners();
    }
  }

  Future<void> delete(String id) async {
    busy = true;
    lastError = '';
    notifyListeners();
    try {
      await service.deleteCrud(uid, collection, id);
    } catch (e) {
      lastError = e.toString();
    } finally {
      busy = false;
      notifyListeners();
    }
  }

  void replaceCache(List<CrudRecord> value) {
    cache = List<CrudRecord>.from(value);
    notifyListeners();
  }

  void clearError() {
    lastError = '';
    notifyListeners();
  }
}

