class CareerFormState001 extends ChangeNotifier {
  String title = '';
  String description = '';
  String category = 'General';
  bool enabled = true;
  bool valid = false;
  void setTitle(String value) {
    title = value;
    validate();
  }

  void setDescription(String value) {
    description = value;
    validate();
  }

  void setCategory(String value) {
    category = value;
    notifyListeners();
  }

  void setEnabled(bool value) {
    enabled = value;
    notifyListeners();
  }

  void validate() {
    valid = title.trim().length >= 2 && description.trim().isNotEmpty;
    notifyListeners();
  }

  void reset() {
    title = '';
    description = '';
    category = 'General';
    enabled = true;
    valid = false;
    notifyListeners();
  }

  Map<String, dynamic> toMap() => {
        'title': title,
        'description': description,
        'category': category,
        'enabled': enabled,
        'valid': valid
      };
}

