class CareerAnalytics001 {
  final int completed;
  final int attempted;
  final int target;
  const CareerAnalytics001(
      {this.completed = 0, this.attempted = 0, this.target = 10});
  double get completionRate =>
      target <= 0 ? 0 : (completed / target).clamp(0.0, 1.0);
  double get accuracy =>
      attempted <= 0 ? 0 : (completed / attempted).clamp(0.0, 1.0);
  int get remaining => (target - completed).clamp(0, target);
  Map<String, num> toMap() => {
        'completed': completed,
        'attempted': attempted,
        'target': target,
        'completionRate': completionRate,
        'accuracy': accuracy,
        'remaining': remaining
      };
}

